package com.internship.eligibility.service;
import com.internship.eligibility.dto.EligibilityResponse; import com.internship.eligibility.entity.*; import com.internship.eligibility.exception.ApiException; import com.internship.eligibility.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*;
@Service public class InternshipService {private final InternshipRepository internships;private final StudentService students;public InternshipService(InternshipRepository i,StudentService s){internships=i;students=s;}
 public List<Internship> all(){return internships.findAll();} public Internship one(Long id){return internships.findById(id).orElseThrow(()->new ApiException("Internship not found",HttpStatus.NOT_FOUND));}
 public EligibilityResponse check(String email,Long id){Internship i=one(id);Student s=students.get(email);List<String> reasons=new ArrayList<>(),missing=new ArrayList<>(),suggestions=new ArrayList<>();boolean branchOk=i.getEligibleBranches().isEmpty()||containsIgnore(i.getEligibleBranches(),s.getBranch());if(!branchOk){reasons.add("Your branch is not eligible for this internship.");suggestions.add("Apply for internships that accept your branch.");}boolean cgpaOk=s.getCgpa()!=null&&(i.getMinCgpa()==null||s.getCgpa()>=i.getMinCgpa());if(!cgpaOk){reasons.add("Your CGPA is below the minimum required CGPA of "+i.getMinCgpa()+".");suggestions.add("Improve your CGPA and check internships with a lower CGPA requirement.");}
 List<String> req=i.getRequiredSkills()==null?List.of():i.getRequiredSkills();List<String> have=s.getSkills()==null?List.of():s.getSkills();long matched=req.stream().filter(x->containsIgnore(have,x)).count();double pct=req.isEmpty()?100.0:Math.round(matched*10000.0/req.size())/100.0;for(String r:req)if(!containsIgnore(have,r))missing.add(r);if(!missing.isEmpty()){reasons.add("You are missing required skills: "+String.join(", ",missing)+".");suggestions.add("Learn the missing skills to improve your eligibility.");}boolean eligible=branchOk&&cgpaOk&&missing.isEmpty();if(eligible)suggestions.add("You meet the current eligibility requirements and can apply.");return new EligibilityResponse(eligible,pct,reasons,missing,suggestions);}
 private boolean containsIgnore(List<String> list,String value){return list.stream().anyMatch(x->x!=null&&value!=null&&x.trim().equalsIgnoreCase(value.trim()));}}
